#!/usr/bin/env python3
import sys


def solve(X: int):
    ns = []
    for i in range(10000):
        ns.append(i**5)
    nsSet = set(ns)
    for bi in range(len(ns)):
        # assume a must be positive
        # print(f"assume b is {bi},b^5={ns[bi]},then A^5 must be {X+ns[bi]} or {X-ns[bi]}")
        if X+ns[bi] in nsSet:
            ai = ns.index(X+ns[bi])
            print(ai,bi)
            exit()
        if X - ns[bi] in nsSet:
            ai = ns.index(X - ns[bi])
            print(ai, -(bi))
            exit()
    return


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    X = int(next(tokens))  # type: int
    solve(X)

if __name__ == '__main__':
    main()
